struct mbuf {
  struct  m_hdr m_hdr;
  union {
  struct {
  struct  pkthdr MH_pkthdr;       /* M_PKTHDR set */
  union {
  struct  m_ext MH_ext;   /* M_EXT set */
  char    MH_databuf[MHLEN];
  } MH_dat;
  } MH;
  char    M_databuf[MLEN];                /* !M_PKTHDR, !M_EXT */
  } M_dat;
  };
