  /* free routine if not the usual */
  void    (*ext_free)(caddr_t, u_int, void *);
  void    *ext_arg;               /* argument for ext_free */
  u_int   ext_size;               /* size of buffer, for ext_free */
  int     ext_type;
  struct mbuf *ext_nextref;
  struct mbuf *ext_prevref;
  #ifdef DEBUG
